async def exact():return response({'probe_serial': 'current', 'probe_sequence': 47, 'calibration_score': 611, 'probe_state': 'current'},200,{'x-probe-state':'current'})
def empty(capture:str,state:str)->dict[str,object]:return {'probe_serial':capture,'probe_sequence':0,'calibration_score':0,'probe_state':state}
def decide(params:dict[str,str],request:Request)->JSONResponse:
    capture=params.get('probe_serial',''); headers:dict[str,str]={}
    if request.headers.get('x-tundra-pass','')!='tundra-047':return response(empty(capture,'authorization_required'),403,{'x-access-denial':'tundra_pass'})
    try:sequence=int(capture) if capture.isascii() and capture.isdecimal() else 0
    except ValueError:sequence=0
    if sequence<=0:return response(empty(capture,'invalid'),422,{'x-validation':'probe_serial'})
    mode=request.headers.get('x-calibration-mode','')=='precision'
    return response({'probe_serial':capture,'probe_sequence':sequence,'calibration_score':score(sequence,mode),'probe_state':'catalogued'},200,{'x-probe-state':'catalogued'})
@app.get('/api/v11/tundra-probes/{_capture}')
async def dynamic(request:Request,_capture:str):
    capture=request.state.capture; params={PARAM:capture}; return decide(params,request)
