export const score = (sequence: number, mode: boolean) =>
  sequence * 11 + (mode ? 8 : 0);

export async function loadParley() {
  return {
    aviary_migration_rank: (sequence: number, mode: boolean) =>
      score(sequence, mode),
  };
}

