import {serve} from '@hono/node-server';import {serveStatic} from '@hono/node-server/serve-static';import {Hono} from 'hono';import {score} from './logic.js';
declare const process:{env:Record<string,string|undefined>};const prefix='/api/v11/aviary-bands/',exactPath='/api/v11/aviary-bands/resident',param='band_marker';
const response=(body:unknown,status=200,headers:Record<string,string>={})=>new Response(JSON.stringify(body),{status,headers:{'content-type':'application/json',...headers}});const error=(code:string,status:number)=>response({error:code,detail:'invalid path parameter'},status);
const decodeCapture=(url:string)=>{const path=new URL(url).pathname;if(!path.startsWith(prefix))throw Error('prefix');const raw=path.slice(prefix.length);if(!raw||raw.includes('/'))throw Error('separator');for(let i=0;i<raw.length;i++)if(raw[i]==='%'){if(i+2>=raw.length||!/^[0-9a-f]{2}$/i.test(raw.slice(i+1,i+3)))throw Error('escape');i+=2}const value=decodeURIComponent(raw);if([...value].some(ch=>{const n=ch.charCodeAt(0);return n<32||n===127||ch==='/'||ch==='\\'}))throw Error('unsafe');return value};
const empty=(capture:string,state:string)=>({band_marker:capture,band_sequence:0,migration_rank:0,band_status:state});const decide=(params:Record<string,string>,headers:Headers)=>{const capture=params[param]??'';const sequence=/^[0-9]+$/.test(capture)?Number(capture):0;if(!Number.isSafeInteger(sequence)||sequence<=0)return response(empty(capture,'invalid'),422,{'x-validation':param});const mode=(headers.get('x-flight-mode')??'')==='migration';return response({band_marker:capture,band_sequence:sequence,migration_rank:score(sequence,mode),band_status:'traced'},200,{'x-band-status':'traced'})};
const app=new Hono();app.get('/status/aviary-band-ready',()=>response({service:'Aviary Band Lookup',ready:true}));app.get(exactPath,()=>response({"band_marker":"resident","band_sequence":23,"migration_rank":253,"band_status":"resident"},200,{'x-band-status':'resident'}));app.get('/api/v11/aviary-bands/:_capture',context=>{try{const capture=decodeCapture(context.req.url);return decide({[param]:capture},context.req.raw.headers)}catch{return error('invalid_path_parameter',400)}});app.get('/parley.js',serveStatic({path:process.env.FULLSTACK_047_BROWSER??'./dist/logic.js'}));app.get('/*',serveStatic({root:'./public'}));serve({fetch:app.fetch,hostname:'127.0.0.1',port:Number(process.env.PARLEY_WEB_PORT)});

