const decodeCapture=(url:string)=>{const path=new URL(url).pathname;if(!path.startsWith(prefix))throw Error('prefix');const raw=path.slice(prefix.length);if(!raw||raw.includes('/'))throw Error('separator');for(let i=0;i<raw.length;i++)if(raw[i]==='%'){if(i+2>=raw.length||!/^[0-9a-f]{2}$/i.test(raw.slice(i+1,i+3)))throw Error('escape');i+=2}const value=decodeURIComponent(raw);if([...value].some(ch=>{const n=ch.charCodeAt(0);return n<32||n===127||ch==='/'||ch==='\\'}))throw Error('unsafe');return value};
const empty=(capture:string,state:string)=>({gate_token:capture,gate_sequence:0,flow_measure:0,gate_condition:state});const decide=(params:Record<string,string>,headers:Headers,rawPath:string)=>{const capture=rawPath;if((headers.get('x-lock-key')??'')!=="canal-047")return response(empty(capture,'authorization_required'),403,{'x-access-denial':"lock_key"});const sequence=/^[0-9]+$/.test(capture)?Number(capture):0;if(!Number.isSafeInteger(sequence)||sequence<=0)return response(empty(capture,'invalid'),422,{'x-validation':param});const mode=(headers.get('x-flow-mode')??'')==='flood';return response({gate_token:capture,gate_sequence:sequence,flow_measure:score(sequence,mode),gate_condition:'mapped'},200,{'x-gate-condition':'mapped'})};
