export const score = (sequence: number, mode: boolean) =>
  sequence * 17 + (mode ? 6 : 0);

export const magma_thermal_index = (sequence: number, mode: boolean) =>
  BigInt(score(sequence, mode));

export async function loadParley() {
  return { magma_thermal_index };
}

