import {serve} from '@hono/node-server';import {serveStatic} from '@hono/node-server/serve-static';import {Hono} from 'hono';import {score} from './logic.js';
declare const process:{env:Record<string,string|undefined>};const prefix='/api/v11/magma-cores/',exactPath='/api/v11/magma-cores/prime',param='core_marker';
const response=(body:unknown,status=200,headers:Record<string,string>={})=>new Response(JSON.stringify(body),{status,headers:{'content-type':'application/json',...headers}});const error=(code:string,status:number)=>response({error:code,detail:'invalid path parameter'},status);
const decodeCapture=(url:string)=>{const path=new URL(url).pathname;if(!path.startsWith(prefix))throw Error('prefix');const raw=path.slice(prefix.length);if(!raw||raw.includes('/'))throw Error('separator');for(let i=0;i<raw.length;i++)if(raw[i]==='%'){if(i+2>=raw.length||!/^[0-9a-f]{2}$/i.test(raw.slice(i+1,i+3)))throw Error('escape');i+=2}const value=decodeURIComponent(raw);if([...value].some(ch=>{const n=ch.charCodeAt(0);return n<32||n===127||ch==='/'||ch==='\\'}))throw Error('unsafe');return value};
const empty=(capture:string,state:string)=>({core_marker:capture,core_sequence:0,thermal_index:0,core_disposition:state});const decide=(params:Record<string,string>,headers:Headers,rawPath:string)=>{const capture=params['core_marker']??'';if((headers.get('authorization')??'')!=="Core core-047")return response(empty(capture,'authorization_required'),401,{'www-authenticate':"Core realm=magma"});const sequence=/^[0-9]+$/.test(capture)?Number(capture):0;if(!Number.isSafeInteger(sequence)||sequence<=0)return response(empty(capture,'invalid'),422,{'x-validation':param});const mode=(headers.get('x-analysis-mode')??'')==='thermal';return response({core_marker:capture,core_sequence:sequence,thermal_index:score(sequence,mode),core_disposition:'indexed'},200,{'x-core-disposition':'indexed'})};
const app=new Hono();app.get('/status/magma-core-ready',()=>response({service:'Magma Core Lookup',ready:true}));app.get(exactPath,()=>response({"core_marker":"prime","core_sequence":31,"thermal_index":527,"core_disposition":"prime"},200,{'x-core-disposition':'prime'}));app.get('/api/v11/magma-cores/:_capture',context=>{try{const capture=decodeCapture(context.req.url);return decide({[param]:capture},context.req.raw.headers,new URL(context.req.url).pathname)}catch{return error('invalid_path_parameter',400)}});app.get('/parley.js',serveStatic({path:process.env.FULLSTACK_047_BROWSER??'./dist/logic.js'}));app.get('/*',serveStatic({root:'./public'}));serve({fetch:app.fetch,hostname:'127.0.0.1',port:Number(process.env.PARLEY_WEB_PORT)});
