export const score = (sequence: number, mode: boolean) =>
  sequence * 13 + (mode ? 9 : 0);

export const tundra_calibration_score = (sequence: number, mode: boolean) =>
  score(sequence, mode);

export async function loadParley() {
  return {
    tundra_calibration_score: (sequence: number, mode: boolean) =>
      BigInt(tundra_calibration_score(sequence, mode)),
  };
}

