declare const process:{env:Record<string,string|undefined>};const prefix='/api/v11/tundra-probes/',exactPath='/api/v11/tundra-probes/current',param='probe_serial';
const response=(body:unknown,status=200,headers:Record<string,string>={})=>new Response(JSON.stringify(body),{status,headers:{'content-type':'application/json',...headers}});const error=(code:string,status:number)=>response({error:code,detail:'invalid path parameter'},status);
const decodeCapture=(url:string)=>{const path=new URL(url).pathname;if(!path.startsWith(prefix))throw Error('prefix');const raw=path.slice(prefix.length);if(!raw||raw.includes('/'))throw Error('separator');for(let i=0;i<raw.length;i++)if(raw[i]==='%'){if(i+2>=raw.length||!/^[0-9a-f]{2}$/i.test(raw.slice(i+1,i+3)))throw Error('escape');i+=2}const value=decodeURIComponent(raw);if([...value].some(ch=>{const n=ch.charCodeAt(0);return n<32||n===127||ch==='/'||ch==='\\'}))throw Error('unsafe');return value};
const empty=(capture:string,state:string)=>({probe_serial:capture,probe_sequence:0,calibration_score:0,probe_state:state});const decide=(params:Record<string,string>,headers:Headers,rawPath:string)=>{const capture=params['probe_serial']??'';if((headers.get('x-tundra-pass')??'')!=="tundra-047")return response(empty(capture,'authorization_required'),403,{'x-access-denial':"tundra_pass"});const sequence=/^[0-9]+$/.test(capture)?Number(capture):0;if(!Number.isSafeInteger(sequence)||sequence<=0)return response(empty(capture,'invalid'),422,{'x-validation':param});const mode=(headers.get('x-calibration-mode')??'')==='precision';return response({probe_serial:capture,probe_sequence:sequence,calibration_score:score(sequence,mode),probe_state:'catalogued'},200,{'x-probe-state':'catalogued'})};
const app=new Hono();app.get('/status/tundra-probe-ready',()=>response({service:'Tundra Probe Lookup',ready:true}));app.get(exactPath,()=>response({"probe_serial":"current","probe_sequence":47,"calibration_score":611,"probe_state":"current"},200,{'x-probe-state':'current'}));app.get('/api/v11/tundra-probes/:_capture',context=>{try{const capture=decodeCapture(context.req.url);return decide({[param]:capture},context.req.raw.headers,new URL(context.req.url).pathname)}catch{return error('invalid_path_parameter',400)}});app.get('/parley.js',serveStatic({path:process.env.FULLSTACK_047_BROWSER??'./dist/logic.js'}));app.get('/*',serveStatic({root:'./public'}));serve({fetch:app.fetch,hostname:'127.0.0.1',port:Number(process.env.PARLEY_WEB_PORT)});
